export interface RegisterDef {
  name: string;
  address: number;
  size: number;
  rw: string;
}

export interface DriverSpec {
  name: string;
  driver_type: string;
  compatible: string;
  bus: string;
  description: string;
  vendor: string;
  has_interrupt: boolean;
  num_channels: number;
  registers: RegisterDef[];
  author: string;
  year: string;
}

export interface GeneratedDriver {
  source_c: string;
  header_h: string;
  kconfig: string;
  cmake: string;
  overlay_sample: string;
  prj_conf_sample: string;
  readme: string;
  test_c: string | null;
}

const SPDX = '/* SPDX-License-Identifier: Apache-2.0 */';

function compatToUnderscore(compatible: string): string {
  return compatible.replace(/,/g, '_').replace(/-/g, '_');
}

function generateRegisterDefines(registers: RegisterDef[]): string {
  if (registers.length === 0) {
    return '/* No registers defined - add your own here */\n';
  }
  return registers
    .map((register) => `#define ${register.name.padEnd(30, ' ')} 0x${register.address.toString(16).toUpperCase().padStart(2, '0')}  /* ${register.rw}, ${register.size} byte(s) */`)
    .join('\n');
}

function busIncludes(bus: string): string {
  if (bus === 'i2c') {
    return '#include <zephyr/drivers/i2c.h>';
  }
  if (bus === 'spi') {
    return '#include <zephyr/drivers/spi.h>';
  }
  return '';
}

function busConfigFields(bus: string): string {
  if (bus === 'i2c') {
    return '    struct i2c_dt_spec i2c;';
  }
  if (bus === 'spi') {
    return '    struct spi_dt_spec spi;\n    struct gpio_dt_spec cs_gpio;';
  }
  return '    /* No bus */';
}

function busDataFields(): string {
  return '    int32_t last_sample;';
}

function busHelpers(bus: string, name: string): string {
  if (bus === 'i2c') {
    return `static int ${name}_reg_read(const struct device *dev,
                               uint8_t reg, uint8_t *val, uint8_t len)
{
    const struct ${name}_config *cfg = dev->config;
    return i2c_burst_read_dt(&cfg->i2c, reg, val, len);
}

static int ${name}_reg_write(const struct device *dev,
                             uint8_t reg, uint8_t val)
{
    const struct ${name}_config *cfg = dev->config;
    return i2c_reg_write_byte_dt(&cfg->i2c, reg, val);
}`;
  }
  if (bus === 'spi') {
    return `/* TODO: Add SPI read/write helpers for ${name} */`;
  }
  return '';
}

function busInitCode(bus: string): string {
  if (bus === 'i2c') {
    return `    if (!i2c_is_ready_dt(&cfg->i2c)) {
        LOG_ERR("I2C bus not ready");
        return -ENODEV;
    }`;
  }
  if (bus === 'spi') {
    return `    if (!spi_is_ready_dt(&cfg->spi)) {
        LOG_ERR("SPI bus not ready");
        return -ENODEV;
    }`;
  }
  return '';
}

function configInitMacro(bus: string): string {
  if (bus === 'i2c') {
    return '        .i2c = I2C_DT_SPEC_INST_GET(inst),                             \\';
  }
  if (bus === 'spi') {
    return '        .spi = SPI_DT_SPEC_INST_GET(inst, SPI_WORD_SET(8), 0),        \\\n        .cs_gpio = GPIO_DT_SPEC_INST_GET(inst, cs_gpios),               \\';
  }
  return '        /* No bus-specific config */                                    \\';
}

function irqHandler(name: string, hasInterrupt: boolean): string {
  if (!hasInterrupt) {
    return '';
  }
  return `/* -- IRQ handling -------------------------------------------------- */

static void ${name}_irq_handler(const struct device *dev)
{
    struct ${name}_data *data = dev->data;

    LOG_DBG("IRQ fired");
    /* TODO: Read status register, clear interrupt, notify */
}`;
}

function triggerApi(hasInterrupt: boolean): string {
  return hasInterrupt ? '    /* .trigger_set = ... */  /* TODO: add trigger support */' : '';
}

function irqInit(hasInterrupt: boolean): string {
  return hasInterrupt ? '    /* TODO: Configure and enable interrupt line */' : '';
}

function generateSensorDriver(spec: DriverSpec): string {
  const nameUpper = spec.name.toUpperCase();
  return `${SPDX}
/**
 * @file ${spec.name}.c
 * @brief Zephyr sensor driver for ${spec.compatible}
 *
 * Generated by Pyontrust Pin Configurator.
 * ${spec.description}
 */

#include <zephyr/device.h>
#include <zephyr/drivers/sensor.h>
${busIncludes(spec.bus)}
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(${spec.name}, CONFIG_${nameUpper}_LOG_LEVEL);

#define DT_DRV_COMPAT ${compatToUnderscore(spec.compatible)}

/* -- Register definitions ------------------------------------------ */

${generateRegisterDefines(spec.registers)}

/* -- Driver data & config ------------------------------------------ */

struct ${spec.name}_config {
${busConfigFields(spec.bus)}
};

struct ${spec.name}_data {
${busDataFields()}
};

/* -- Bus helpers --------------------------------------------------- */

${busHelpers(spec.bus, spec.name)}

/* -- Sensor API ---------------------------------------------------- */

static int ${spec.name}_sample_fetch(const struct device *dev,
                               enum sensor_channel chan)
{
    struct ${spec.name}_data *data = dev->data;
    const struct ${spec.name}_config *cfg = dev->config;

    /* TODO: Read sensor registers and update data->last_sample */
    LOG_DBG("sample_fetch called");

    return 0;
}

static int ${spec.name}_channel_get(const struct device *dev,
                              enum sensor_channel chan,
                              struct sensor_value *val)
{
    struct ${spec.name}_data *data = dev->data;

    switch (chan) {
    case SENSOR_CHAN_ALL:
        /* TODO: Fill val with the appropriate channel data */
        val->val1 = 0;
        val->val2 = 0;
        break;
    default:
        return -ENOTSUP;
    }

    return 0;
}

${irqHandler(spec.name, spec.has_interrupt)}

static const struct sensor_driver_api ${spec.name}_api = {
    .sample_fetch = ${spec.name}_sample_fetch,
    .channel_get  = ${spec.name}_channel_get,
${triggerApi(spec.has_interrupt)}
};

/* -- Init ---------------------------------------------------------- */

static int ${spec.name}_init(const struct device *dev)
{
    const struct ${spec.name}_config *cfg = dev->config;

    LOG_INF("${spec.name} initialized on %s", dev->name);
${busInitCode(spec.bus)}
${irqInit(spec.has_interrupt)}
    return 0;
}

/* -- Instantiation ------------------------------------------------- */

#define ${nameUpper}_INST(inst)                                                   \
    static struct ${spec.name}_data ${spec.name}_data_##inst;                           \
                                                                            \
    static const struct ${spec.name}_config ${spec.name}_config_##inst = {              \
${configInitMacro(spec.bus)}
    };                                                                     \
                                                                            \
    DEVICE_DT_INST_DEFINE(inst,                                             \
                          ${spec.name}_init,                                       \
                          NULL,                                              \
                          &${spec.name}_data_##inst,                               \
                          &${spec.name}_config_##inst,                             \
                          POST_KERNEL,                                       \
                          CONFIG_${nameUpper}_INIT_PRIORITY,                       \
                          &${spec.name}_api);

DT_INST_FOREACH_STATUS_OKAY(${nameUpper}_INST)
`;
}

function generateCustomDriver(spec: DriverSpec): string {
  const nameUpper = spec.name.toUpperCase();
  return `${SPDX}
/**
 * @file ${spec.name}.c
 * @brief Zephyr device driver for ${spec.compatible}
 *
 * Generated by Pyontrust Pin Configurator.
 * ${spec.description}
 */

#include <zephyr/device.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(${spec.name}, CONFIG_${nameUpper}_LOG_LEVEL);

#define DT_DRV_COMPAT ${compatToUnderscore(spec.compatible)}

/* -- Driver data & config ------------------------------------------ */

struct ${spec.name}_config {
    /* Add device-specific config fields here */
};

struct ${spec.name}_data {
    /* Add runtime data fields here */
};

/* -- API ----------------------------------------------------------- */

/* TODO: Define your driver API struct and functions */

/* -- Init ---------------------------------------------------------- */

static int ${spec.name}_init(const struct device *dev)
{
    const struct ${spec.name}_config *cfg = dev->config;

    LOG_INF("${spec.name} initialized on %s", dev->name);

    return 0;
}

/* -- Instantiation ------------------------------------------------- */

#define ${nameUpper}_INST(inst)                                                   \
    static struct ${spec.name}_data ${spec.name}_data_##inst;                           \
                                                                            \
    static const struct ${spec.name}_config ${spec.name}_config_##inst = {              \
    };                                                                     \
                                                                            \
    DEVICE_DT_INST_DEFINE(inst,                                             \
                          ${spec.name}_init,                                       \
                          NULL,                                              \
                          &${spec.name}_data_##inst,                               \
                          &${spec.name}_config_##inst,                             \
                          POST_KERNEL,                                       \
                          CONFIG_${nameUpper}_INIT_PRIORITY,                       \
                          NULL);

DT_INST_FOREACH_STATUS_OKAY(${nameUpper}_INST)
`;
}

function generateKconfig(spec: DriverSpec): string {
  const nameUpper = spec.name.toUpperCase();
  const busDep = spec.bus === 'i2c' ? '\n\tselect I2C' : spec.bus === 'spi' ? '\n\tselect SPI' : '';
  return `# SPDX-License-Identifier: Apache-2.0

config ${nameUpper}
\tbool "Enable ${spec.name} driver"
\tdefault y
\tdepends on DT_HAS_${compatToUnderscore(spec.compatible).toUpperCase()}_ENABLED${busDep}
\thelp
\t  Enable the ${spec.name} driver for ${spec.compatible} devices.
\t  ${spec.description}

if ${nameUpper}

config ${nameUpper}_INIT_PRIORITY
\tint "${spec.name} init priority"
\tdefault 90
\thelp
\t  Initialization priority for the ${spec.name} driver.

config ${nameUpper}_LOG_LEVEL
\tint "${spec.name} log level"
\tdefault 4
\trange 0 4
\thelp
\t  Log level for the ${spec.name} driver (0=OFF, 4=DBG).

endif # ${nameUpper}
`;
}

function generateCmake(spec: DriverSpec): string {
  return `# SPDX-License-Identifier: Apache-2.0

zephyr_library_sources_ifdef(CONFIG_${spec.name.toUpperCase()} ${spec.name}.c)
`;
}

function generateOverlaySample(spec: DriverSpec): string {
  if (spec.bus === 'i2c') {
    return `/* Sample DTS overlay for ${spec.compatible} on I2C bus */
&i2c0 {
    status = "okay";

    ${spec.name}: ${spec.name}@XX {
        compatible = "${spec.compatible}";
        reg = <0xXX>;  /* TODO: Set I2C address */
        status = "okay";
    };
};
`;
  }
  if (spec.bus === 'spi') {
    return `/* Sample DTS overlay for ${spec.compatible} on SPI bus */
&spi0 {
    status = "okay";

    ${spec.name}: ${spec.name}@0 {
        compatible = "${spec.compatible}";
        reg = <0>;
        spi-max-frequency = <1000000>;
        status = "okay";
    };
};
`;
  }
  return `/* Sample DTS overlay for ${spec.compatible} */
/ {
    ${spec.name}: ${spec.name} {
        compatible = "${spec.compatible}";
        status = "okay";
    };
};
`;
}

function generatePrjConfSample(spec: DriverSpec): string {
  const lines = [
    `# Enable the ${spec.name} driver`,
    `CONFIG_${spec.name.toUpperCase()}=y`,
    `CONFIG_${spec.name.toUpperCase()}_LOG_LEVEL=4`,
  ];
  if (spec.driver_type === 'sensor') {
    lines.push('CONFIG_SENSOR=y');
  }
  if (spec.bus === 'i2c') {
    lines.push('CONFIG_I2C=y');
  } else if (spec.bus === 'spi') {
    lines.push('CONFIG_SPI=y');
  }
  lines.push('CONFIG_LOG=y');
  return `${lines.join('\n')}\n`;
}

